using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using Microsoft.VisualStudio.TestPlatform.ObjectModel;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Classes")]
    [TestClass]
    public class RJIT_CR_BC_C_00002 : MsTestBase
    {
        /*
         * Code Rule RJIT_CR_BC_C_00002 enforces that classes should not have mutable properties. This rule aims to promote immutability within classes, which can lead to safer and more predictable code, especially in multithreaded environments.
         */
        [TestMethod]
        public void Classes_Should_Not_Have_Mutable_Properties()
        {
            var returnAwaitOnly = (from @class in Classes
                                   where @class.Modifiers.Contains(Modifier.Static).IsFalse()
                                         && @class.Attributes.Any(a => a.Name.Contains("TestClass")).IsFalse() // Ignore test classes
                                   from property in @class.Properties
                                   where property.IsReadOnly.IsFalse()
                                   && property.Modifiers.Contains(Modifier.Static).IsFalse() && property.SyntaxTree.Contains("private set;").IsFalse()
                                   select new
                                   {
                                       ErrorClass = @class.FullQualifiedName,
                                       ErrorProperty = $"{property.Type} {property.Name}",
                                       Error = $@"

Please do not use mutable property signatures.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FullName:  {@class.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Property:  {property.Type} {property.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Should be: {property.Type} {property.Name} {{get; init;}}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                   }).ToImmutableList();

            Assert.IsTrue(returnAwaitOnly.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_BC_C_00002

Properties must be immutable. Findings: '{returnAwaitOnly.Count}':{Environment.NewLine}{returnAwaitOnly.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
